function validate([root, voyage]) {
  if (root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  let open = 1;
  for (const v of root) {
    if (open === 0) return 'Every value after the root needs a parent node.';
    open += v === null ? -1 : 1;
  }
  const values = root.filter(v => v !== null);
  const n = values.length;
  if (n > 100) return 'The tree has at most 100 nodes.';
  if (voyage.length !== n) return 'voyage needs exactly one value per tree node.';
  if (new Set(values).size !== n || values.some(v => !Number.isInteger(v) || v < 1 || v > n)) return 'The tree values must be 1 to n, each used once.';
  if (new Set(voyage).size !== n || voyage.some(v => !Number.isInteger(v) || v < 1 || v > n)) return 'voyage must hold 1 to n, each once.';
  return null;
}

