function flipMatchVoyage(root, voyage) {
  const size = node => node ? 1 + size(node.left) + size(node.right) : 0;
  // Flips that make node's preorder equal voyage[start ...], or null when impossible.
  const match = (node, start) => {
    if (!node) return [];
    if (node.val !== voyage[start]) return null;
    const first = node.left, second = node.right;
    const options = [];
    const left = match(first, start + 1);
    const right = left && match(second, start + 1 + size(first));
    if (left && right) options.push([...left, ...right]);
    if (first && second) {
      const swappedRight = match(second, start + 1);
      const swappedLeft = swappedRight && match(first, start + 1 + size(second));
      if (swappedRight && swappedLeft) options.push([node.val, ...swappedRight, ...swappedLeft]);
    }
    if (!options.length) return null;
    return options.reduce((a, b) => (b.length < a.length ? b : a));
  };
  const answer = match(root, 0);
  return answer === null ? [-1] : answer;
}

