function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 100 : 1 + pick(8);
  const values = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = pick(i + 1);
    [values[i], values[j]] = [values[j], values[i]];
  }
  const nodes = [{ val: values[0], left: null, right: null }];
  const deep = rand() < 0.3;
  while (nodes.length < n) {
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(2))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side]) continue;
    const node = { val: values[nodes.length], left: null, right: null };
    parent[side] = node;
    nodes.push(node);
  }
  // Usually the voyage is the preorder after some random flips, so it is reachable.
  const flipChance = rand();
  const voyage = [];
  const walk = node => {
    if (!node) return;
    voyage.push(node.val);
    if (rand() < flipChance) { walk(node.right); walk(node.left); } else { walk(node.left); walk(node.right); }
  };
  walk(nodes[0]);
  const mode = rand();
  if (mode < 0.15) {
    for (let i = n - 1; i > 0; i--) {
      const j = pick(i + 1);
      [voyage[i], voyage[j]] = [voyage[j], voyage[i]];
    }
  } else if (mode < 0.35 && n >= 2) {
    const i = pick(n), j = pick(n);
    [voyage[i], voyage[j]] = [voyage[j], voyage[i]];
  }
  const out = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out, voyage];
}
